import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';

// --- DashboardBellAndMenu (Bell is now a separate, clean icon) ---
const DashboardBellAndMenu = ({ onMenuClick, isEasyMode, t, toggleAlert, isAlertExpanded }) => ( 
    <div style={{ 
        position: 'absolute', 
        top: '15px', // Consistent top position
        right: '15px',
        zIndex: 100,
        display: 'flex',
        alignItems: 'center',
    }}>
        {/* 1. BLINKING BELL ICON (Toggles the alert and is slightly animated) */}
        <button
            onClick={toggleAlert}
            style={{ 
                // Styling to make the bell pop
                padding: '8px',
                backgroundColor: isAlertExpanded ? '#FFC107' : 'transparent', // Highlight background when expanded
                border: isAlertExpanded ? '2px solid #856404' : 'none',
                borderRadius: '50%',
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                animation: isAlertExpanded ? 'none' : 'blink-bell 1.5s infinite alternate',
                marginRight: '15px',
                transition: 'all 0.3s ease-out'
            }}
        >
            <span role="img" aria-label={t('general.alert')}>🔔</span>
        </button>

        {/* 2. MENU BUTTON */}
        <button
            onClick={onMenuClick}
            style={{ 
                padding: '8px',
                backgroundColor: 'transparent', 
                border: 'none', 
                cursor: 'pointer',
                fontSize: isEasyMode ? '36px' : '28px', 
                color: '#333',
                transition: 'color 0.2s',
            }}
            onMouseOver={e => e.currentTarget.style.color = '#1A73E8'} 
            onMouseOut={e => e.currentTarget.style.color = '#333'}
        >
            <span role="img" aria-label={t('general.menu')}>☰</span>
        </button>
    </div>
);
// --- END DashboardBellAndMenu ---


// --- Icon Component Modification (No changes needed, omitted for brevity) ---
const Icon = ({ name, emoji, isActive, onClick, isProminent, isEasyMode, keyName, color = '#1A73E8', bgColor = '#E8F0FE' }) => {
    
    // ... Icon logic and styling remain the same ...

    const isColored = isActive || isProminent; 
    let iconColor = color;
    let iconBgColor = '#E8F0FE'; 
    
    if (keyName === "dashboard.emergency_info_card") {
        iconColor = '#DC3545';
        iconBgColor = '#FDE9E9';
    } else if (keyName === "medical_menu.access_card_short") {
        iconColor = '#1A73E8';
        iconBgColor = '#E8F0FE';
    } else if (keyName === "dashboard.medical_history_card") {
        iconColor = '#17A2B8';
        iconBgColor = '#E8F7F9';
    }
    
    const baseFontSize = isEasyMode ? 32 : 18;
    let labelFontSize = baseFontSize;

    if (name && name.length > 12) {
        labelFontSize = isEasyMode ? 24 : 16;
    }


    return (
        <div 
            onClick={onClick} 
            style={{
                padding: '25px', 
                margin: '15px',
                border: `5px solid ${isColored ? iconColor : '#e0e0e0'}`,
                borderRadius: '15px', 
                width: '40%',
                textAlign: 'center',
                backgroundColor: isColored ? iconBgColor : '#ffffff',
                filter: isColored ? 'none' : 'grayscale(80%)',
                opacity: isColored ? 1 : 0.7, 
                cursor: 'pointer',
                boxShadow: isColored ? `0 8px 15px ${iconColor}4D` : '0 2px 5px rgba(0, 0, 0, 0.1)',
                transition: 'all 0.3s',
                fontSize: `${labelFontSize}px`, 
            }}
        >
            <span role="img" aria-label={name} style={{fontSize: isEasyMode ? '85px' : '40px', display: 'block', marginBottom: '10px'}}>{emoji}</span>
            <p style={{fontWeight: 'bold', color: '#333', margin: 0}}>{name}</p>
        </div>
    );
};
// --- END Icon Component Modification ---


function Dashboard({ isEasyMode, goToMedical, onMenuClick, goToEmergencyInfo }) { 
    const { t } = useTranslation();
    const [isAlertExpanded, setIsAlertExpanded] = useState(false); 

    const showAppointmentNotification = true; 
    
    const toggleAlert = () => setIsAlertExpanded(prev => !prev);
    
    // REFINED SLIDE-OUT STYLING for better looks
    const notificationStyle = {
        padding: '15px 20px', 
        backgroundColor: '#FFF3CD', 
        color: '#856404', 
        cursor: 'pointer',
        fontWeight: 'bold',
        borderRadius: '10px', 
        border: '3px solid #FFC107', 
        boxShadow: '0 8px 15px rgba(255, 193, 7, 0.3)',
        zIndex: 90, 
        
        display: 'flex', 
        flexDirection: 'column', 
        alignItems: 'flex-start',
        
        // Use a calculated width to fit neatly beside the bell/menu
        width: isAlertExpanded ? 'calc(100% - 100px)' : '0', 
        height: isAlertExpanded ? 'auto' : '0',
        overflow: 'hidden',
        whiteSpace: 'nowrap',
        opacity: isAlertExpanded ? 1 : 0,

        // ABSOLUTE POSITIONING for slide-out effect
        position: 'absolute',
        top: '15px', // Aligns with the DashboardBellAndMenu
        right: '90px', // Starts just to the left of the bell icon
        
        // TRANSITION: Apply smooth visual change
        transition: 'width 0.4s ease-out, opacity 0.3s ease-in 0.1s, height 0.4s ease-out',
        pointerEvents: isAlertExpanded ? 'auto' : 'none', 
    };

    // Styling for the text inside the banner
    const alertTextStyle = {
        fontSize: isEasyMode ? '24px' : '16px',
        fontWeight: 'bold',
        display: 'block',
        lineHeight: '1.2'
    }


    return (
        <div style={{ position: 'relative' }}>
            
            {/* 1. BELL & MENU BUTTONS (Always visible) */}
            <DashboardBellAndMenu 
                onMenuClick={onMenuClick} 
                isEasyMode={isEasyMode} 
                t={t}
                toggleAlert={toggleAlert}
                isAlertExpanded={isAlertExpanded}
            />

            {/* 2. THE SLIDE-OUT NOTIFICATION BANNER */}
            {showAppointmentNotification && (
                // Only allow click-to-navigate when alert is expanded
                <div 
                    onClick={isAlertExpanded ? goToMedical : undefined} 
                    style={notificationStyle}
                >
                    <span style={alertTextStyle}>
                        {t('dashboard.appointment_soon_alert')}
                    </span>
                    <span style={{...alertTextStyle, fontSize: isEasyMode ? '32px' : '22px'}}>
                        {t('general.tap_here')}
                    </span>
                </div>
            )}


            {/* 3. MAIN ICON GRID (Pushed down to start below the header area) */}
            <div style={{ 
                display: 'flex', 
                flexWrap: 'wrap', 
                justifyContent: 'center', 
                paddingTop: '100px', // Enough space for header/alert
                paddingBottom: '40px' 
            }}>
                
                {/* Icons... (no change) */}
                <Icon 
                    name={t('medical_menu.access_card_short')} 
                    emoji="🏥" 
                    isActive={true} 
                    onClick={goToMedical} 
                    isEasyMode={isEasyMode}
                    keyName={'medical_menu.access_card_short'} 
                />
                
                <Icon 
                    name={t('dashboard.emergency_info_card')} 
                    emoji="🆘" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={goToEmergencyInfo} 
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.emergency_info_card'} 
                />
                
                <Icon 
                    name={t('dashboard.medical_history_card')} 
                    emoji="📜" 
                    isProminent={true} 
                    isActive={false} 
                    onClick={() => console.log('Medical History page route needed.')}
                    isEasyMode={isEasyMode}
                    keyName={'dashboard.medical_history_card'} 
                />
                
                <div style={{ width: '40%', margin: '15px', visibility: 'hidden' }}></div>
            </div>

            {/* CSS Animation for the Bell */}
            <style jsx>{`
                @keyframes blink-bell {
                    0% { 
                        transform: scale(1); 
                        opacity: 1;
                        text-shadow: 0 0 5px #FFC107;
                    }
                    50% { 
                        transform: scale(1.05); 
                        opacity: 0.8;
                        text-shadow: none;
                    }
                    100% { 
                        transform: scale(1); 
                        opacity: 1;
                        text-shadow: 0 0 5px #FFC107;
                    }
                }
            `}</style>
        </div>
    );
}

export default Dashboard;
